import{_ as a,o as t,c as n,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const d=JSON.parse('{"title":"Can Your Model Separate Yolks with a Water Bottle? Benchmarking Physical Commonsense Understanding in Video Generation Models","description":"","frontmatter":{"title":"Can Your Model Separate Yolks with a Water Bottle? Benchmarking Physical Commonsense Understanding in Video Generation Models","arxiv":"2507.15824","date":"2025-07-21","authors":"Enes Sanli, Baris Sarper Tezcan, Aykut Erdem, Erkut Erdem","categories":"cs.CV","topics":"物理感知视频生成, benchmark, 工具使用与 affordance","outline":[2,2]},"headers":[],"relativePath":"papers/2507.15824.md","filePath":"papers/2507.15824.md","lastUpdated":null}'),e={name:"papers/2507.15824.md"};function r(o,s,l,i,m,c){return t(),n("div",null,[...s[0]||(s[0]=[p('<h1 id="can-your-model-separate-yolks-with-a-water-bottle-benchmarking-physical-commonsense-understanding-in-video-generation-models" tabindex="-1">Can Your Model Separate Yolks with a Water Bottle? Benchmarking Physical Commonsense Understanding in Video Generation Models <a class="header-anchor" href="#can-your-model-separate-yolks-with-a-water-bottle-benchmarking-physical-commonsense-understanding-in-video-generation-models" aria-label="Permalink to &quot;Can Your Model Separate Yolks with a Water Bottle? Benchmarking Physical Commonsense Understanding in Video Generation Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2507.15824" target="_blank" rel="noreferrer">2507.15824</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-07-21</td></tr><tr><td><strong>作者</strong></td><td>Enes Sanli, Baris Sarper Tezcan, Aykut Erdem, Erkut Erdem</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把 PIQA 的 383 条&quot;生活妙招&quot;改写成基础与增强两套 T2V prompt，用 AuroraCap 为每段生成视频写 8 条分维度 caption，再让 Gemini-2.5-Flash 只凭 caption 回答 4123 道真值全为 Yes 的物理问题，以此绕开 VLM 直接看视频时的幻觉。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><p>作者来自 Koç University、KUIS AI 与 Hacettepe University，项目页 <code>cyberiada.github.io/PhysVidBench</code>，数据集与评测代码已开源。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文标题本身就是问题陈述：你的模型能用一个水瓶把蛋黄从蛋清里分出来吗？这个厨房技巧的物理链条是——捏扁塑料瓶排出空气，把瓶口对准蛋黄，松手时瓶内负压把蛋黄吸进去，蛋清因为黏度与表面张力不同被留下。要把它画对，模型必须同时掌握瓶身的可形变性、气压差、蛋黄与蛋清的材料差异，以及&quot;捏—对准—松手—抬起&quot;这一串必须按序发生的动作。</p><p>作者的判断是：T2V 在视觉吸引力与时序连贯性上已经不错，但在基本物理常识上经常失手，输出违反关于因果关系、物体行为与工具使用的直觉预期。工具使用是这里的关键词。一把剪刀、一个瓶子、一根撬棍，它们的价值不在外观而在 affordance——能对什么物体做什么事。论文明确把 affordance 与工具中介的动作列为当前 T2V 评测的盲区。</p><p>落到具体做法上，PhysVidBench 没有自己编造场景，而是从 <strong>PIQA</strong> 这个纯文本的物理常识数据集里取材：PIQA 的每条样本是一个日常目标加两个候选解法，其中正确解法往往就是一个&quot;生活妙招&quot;。作者把这些解法改写成可以直接喂给 T2V 的视频 prompt，并把物理推理拆成<strong>七个维度</strong>（Fundamental Physics、Object Properties &amp; Affordances、Spatial Reasoning、Temporal Dynamics、Action &amp; Procedural Understanding、Material Interaction &amp; Transformation、Force and Motion）。这样 benchmark 测的不是抽象物理定律，而是人真的会用到的那部分物理知识。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文点名了三条线，并给出了各自的缺口。</p><p><strong>物理专项 benchmark</strong>：PhyGenBench 是律法中心的，围绕浮力、应力、弹性这类<strong>孤立</strong>的物理原理，场景多为被动发生（挤海绵、弹球），没有智能体驱动的工具使用与多步操作；VideoPhy 与 VideoPhy-2 是动作中心的，关注运动是否合理、有无违反物理，但同样很少涉及有目的的工具操控与因果动作链，且依赖 VLM 打分；VBench-2.0 覆盖面最广（State Change、Geometry、Motion Rationality、Instance Preservation），但它基于预定义的推理类别，用的是<strong>多问题 VLM 评测 pipeline</strong>，作者认为视觉 grounding 不够强；Physics-IQ 用真实多视角视频测流体、光学、磁学；Impossible Videos 走的是反面路线，故意构造违反物理的奇观（永不减少的倒水、越弹越高的铁球），能暴露明显错误但缺乏真实世界的目标导向。</p><p><strong>通用生成指标</strong>：CLIPScore、FVD、IS 只刻画分布相似度或多样性，与人类判断经常不一致；VBench、EvalCrafter、FETV 提升了粒度，但基本不碰物理常识。</p><p><strong>语言与多模态侧</strong>：PIQA 上人类接近满分而 LLM 明显落后；PhysBench 评了 75 个 VLM，结论是它们对物理世界的理解仍然薄弱，作者归因于训练数据里缺少物理知识。这两条正是&quot;让 VLM 直接判物理&quot;不可靠的文献依据。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>只用这篇论文之前已存在的东西来推演，路径相当自然。</p><p>第一步来自 PIQA 本身：那里已经有上万条人写的物理常识题，且已知&quot;人接近满分、模型落后&quot;。把文本题渲染成视频，就得到一批天然带正确答案的物理场景，不需要新造数据。作者从训练集与验证集里取出正确解法，得到超过 17,000 条 goal–solution 对。</p><p>第二步是筛选。大部分 PIQA 解法只是工具的常规用法（用毛巾擦手、用熨斗熨衣服），画对它们不需要物理理解。真正要命的是<strong>挪用</strong>——用信用卡刮冰、用回形针捅 SIM 卡托、用瓶子吸蛋黄。作者用 Gemini 2.5 Pro 只保留&quot;二次用途&quot;的样本。</p><p>第三步来自 PhyT2V 的已有结论：把物理属性写进 prompt 能提升生成的物理合理性。于是每条 base prompt 再做一次 upsampling，补上材质、刚度、受力、环境条件，但严禁引入新物体或新结果。这样同一场景就有了&quot;简短&quot;与&quot;物理显式&quot;两个版本，可以直接量出模型对物理细节的响应度。</p><p>第四步是评测方式。既然 VLM 在&quot;看视频 + 判物理&quot;这个复合任务上会走捷径，就把任务拆开：VLM 只做描述，语言模型只做判断。语言模型看不到视频，理论上无法用视觉先验脑补。这是一种刻意制造的信息瓶颈。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>物理常识的难点不在自由落体，而在工具——工具把&quot;物体的属性&quot;变成&quot;可以用来做什么&quot;，这一层知识无法从像素统计里学到，而 PIQA 已经把它整理好了，只差渲染成视频。评测侧则做一次信息瓶颈：先把视频压成八条分维度文字，再让一个看不见视频的语言模型据此答题，理由是答题者失去视觉先验后就没法替画面圆谎。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以&quot;用旧牙刷蘸白漆弹出星空&quot;这条真实样例贯穿全流程。</p><p><strong>构建阶段（四步）</strong></p><ol><li>从 PIQA 训练集 + 验证集取出正确解法，共 17,000 多条 goal–solution 对（测试集无标签，排除）。例：目标&quot;如何在黑背景上画星星&quot;，解法&quot;用沾了白漆的旧牙刷弹向背景&quot;。</li><li>用 <strong>Gemini-2.5-Pro-Preview-05-06</strong> 做二分类筛选，只保留涉及<strong>二次用途或非显而易见 affordance</strong> 的样本（prompt 里给了&quot;水瓶→分蛋器&quot;、&quot;发网→吸尘器滤网&quot;这类示例）。</li><li>同一个 Gemini 2.5 Pro 把筛后样本改写成 10 秒以内、可直接观察的短视频 prompt，产出 <strong>383 条 base prompt</strong>。例：&quot;A person dips an old toothbrush in white paint and flicks it onto a black background, creating stars.&quot;</li><li>再做一次 <strong>upsampling</strong>，补上材质、黏度、受力、重力、表面类型，但明令禁止引入新物体或描述动作之后的结果，得到 <strong>383 条 upsampled prompt</strong>。两套合计 <strong>766 条</strong>，每个被测模型对两套各生成一遍。</li></ol><p><strong>评测阶段（三步）</strong></p><ol><li><strong>物理问题生成</strong>：Gemini 2.5 Pro 从 <strong>upsampled prompt</strong>（而非视频）生成 yes/no 问题，每题标上一个或多个维度。全库共 <strong>4123 道题，平均每段视频 11 道</strong>。关键设计：<strong>所有题的真值都是 Yes</strong>，作者删掉了答案为 No 的题，理由是它们常常能用表面视觉线索平凡地答对。例题：&quot;Did droplets of paint detach from the bristles?&quot;、&quot;Was the detachment caused by the force of the flick?&quot;</li><li><strong>稠密 captioning</strong>：每段生成视频用 <strong>AuroraCap</strong> 写 <strong>8 条 caption</strong>：1 条通用 + 7 条对应七个维度的定向描述（&quot;描述空间布局与物体位置…&quot;、&quot;描述力如何施加与被阻抗…&quot;），prompt 末尾强制要求只写能直接观察到的内容。</li><li><strong>LLM 作判</strong>：把 8 条 caption 与全部问题拼成一个 prompt，交给 <strong>Gemini-2.5-Flash-Preview-04-17</strong>，它看不到视频也看不到原 prompt。判定规则是：<strong>只要 8 条 caption 里有任意一条支持，就答 Yes 并计为正确</strong>。最终分数是答对题的比例。</li></ol><p><strong>难度分层</strong>：取四个最强开源模型（Cosmos、Hunyuan、MAGI-1、Wan2.1）在每条 prompt 上的平均正确率分档：&gt;40% 为 medium（123 条），20–40% 为 hard（160 条），&lt;20% 为 very hard（100 条）。前两档公开，very hard 留作后续评测。作者特意声明没有 easy 档，因为 medium 对现有模型已经很难。</p><p><strong>评测开销</strong>：全部评测在单张 <strong>NVIDIA A40</strong> 上完成，每个模型的分辨率/帧数/时长/guidance scale 固定为官方推荐值并在 base 与 upsampled 两套 prompt 间保持一致（例如 Wan2.1 为 832×480、33 帧、6 秒、guidance 5，HunyuanVideo 为 960×544、129 帧、5 秒、guidance 6）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><p>不过有一个可以直接从评分规则推出的性质值得写下（属于<strong>基于证据的推断</strong>，论文未讨论）：设第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span> 条 caption 支持第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 题的事件为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">ij</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，由于真值恒为 Yes、且判定规则是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.3898em;vertical-align:-0.4358em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">⋁</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">8</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4358em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">ij</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，分数</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">Acc</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.2421em;vertical-align:-1.4138em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mord"><span class="delimsizing size2">[</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8011em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">⋁</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">8</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.4138em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">ij</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size2">]</span></span></span></span></span></span></p><p>对每一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">ij</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 都是<strong>单调不减</strong>的。也就是说，caption 写得越多、越敢描述，分数只会升不会降；而因为题库里没有一道 No 题，这个单调性没有任何反向惩罚项来平衡。这是 § 9 要讨论的那条假设的形式化表述。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>测了谁</strong>：十二个 T2V 系统——VideoCrafter2、CogVideoX-2B/5B、Wan2.1-1.3B/14B、Cosmos-7B/14B、HunyuanVideo、LTX-Video、MAGI-1，加上闭源的 Sora 与 Veo-2。</p><p><strong>模型到底多差？</strong> 以难度分层的成绩看（upsampled prompt，括号内为换成 base prompt 后的变化）：</p><table tabindex="0"><thead><tr><th>模型</th><th>Medium</th><th>Hard</th><th>Very Hard</th></tr></thead><tbody><tr><td>LTX-Video</td><td>41.2 (-1.6)</td><td>22.8 (-4.4)</td><td>9.1 (-1.2)</td></tr><tr><td>VideoCrafter2</td><td>44.5 (-4.3)</td><td>23.1 (-1.1)</td><td>10.7 (-1.6)</td></tr><tr><td>CogVideoX-2B</td><td>49.8 (-7.8)</td><td>28.2 (-3.2)</td><td>11.6 (-0.6)</td></tr><tr><td>CogVideoX-5B</td><td>39.2 (-2.7)</td><td>22.0 (-0.7)</td><td>11.3 (-1.1)</td></tr><tr><td>Wan2.1-1.3B</td><td>57.4 (-3.8)</td><td>33.8 (-4.7)</td><td>14.6 (-1.3)</td></tr><tr><td>Wan2.1-14B</td><td>61.5 (-4.8)</td><td>37.0 (-2.7)</td><td>18.0 (+0.2)</td></tr><tr><td>MAGI-1</td><td>60.5 (-10.7)</td><td>35.2 (-5.5)</td><td>16.8 (-3.2)</td></tr><tr><td>HunyuanVideo</td><td>52.6 (-4.5)</td><td>33.5 (-5.1)</td><td>15.9 (-4.8)</td></tr><tr><td>Cosmos-7B</td><td>60.5 (-10.7)</td><td>38.8 (-10.3)</td><td>18.6 (-5.0)</td></tr><tr><td>Cosmos-14B</td><td>59.2 (-13.1)</td><td>39.2 (-8.7)</td><td>22.2 (-2.2)</td></tr><tr><td>Sora</td><td>52.6 (-2.5)</td><td>34.0 (+0.1)</td><td>15.9 (+2.1)</td></tr><tr><td>Veo-2</td><td>53.3 (-1.5)</td><td>35.6 (-0.1)</td><td>21.1 (-0.2)</td></tr></tbody></table><p>最弱的 LTX-Video 在七维度上的平均分只有 20.7（base prompt 下再降 2.8）。即使是 Cosmos-14B 这样的最强选手，very hard 子集也只到 22.2。</p><p><strong>哪些维度最难？</strong> 作者给出的结论是 <strong>Spatial Reasoning 与 Temporal Dynamics 始终最差</strong>，包括 Wan2.1-14B、Cosmos-14B、Sora、Veo-2 在内；而 <strong>Object Properties &amp; Affordances 反而是最容易的</strong>。作者对后者的解释是模型可能只是在用视觉启发式识别&quot;软/硬/能装东西&quot;，并不代表真的因果理解。</p><p><strong>Prompt 写得更物理有用吗？</strong> 大多数模型在 upsampled prompt 上更好，且大模型获益更多：论文称 Cosmos-7B 提升超过 8 分、Cosmos-14B 提升 7 分，而 LTX-Video 与 VideoCrafter2 不足 3 分。上表里 Cosmos-14B 在 medium 档的 -13.1 直接展示了这个落差。<strong>Sora 是反例</strong>：它在 base prompt 上反而更好（hard +0.1、very hard +2.1），作者推测它内部已经自带 prompt 改写，但因为闭源无法诊断。</p><p><strong>扩大参数量有用吗？</strong> 部分有用。Wan2.1-14B 全面胜过 1.3B，Cosmos-7B 也明显强于更小的模型；但 <strong>CogVideoX-2B 在每一个类别上都赢了 CogVideoX-5B</strong>。作者的结论是 scaling 曲线很平，光堆参数不解决物理推理。</p><p><strong>这套自动评测和人对得上吗？</strong> 作者做了 Qualtrics 人工研究：取四个最强开源模型（Cosmos-14B、Wan2.1-14B、MAGI-1、HunyuanVideo）与随机抽的 30 条 prompt，共 120 段视频；15 名参与者给出 1,340 个二元回答。自动分与人工分的 Pearson 相关为 Cosmos <strong>0.69</strong>、Hunyuan <strong>0.61</strong>、MAGI-1 <strong>0.60</strong>、Wan2.1 <strong>0.45</strong>。另外，MAGI-1 上只有一人作答的题相关只有 0.47，三人以上作答的升到 0.69；作者因此只报告三人以上作答的题。这个区间说明一致性是中等而非强，<strong>尤其 Wan2.1 的 0.45 意味着在那个模型上自动分只能解释人工分约两成方差</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：T2V 的物理短板集中在工具挪用与程序性交互，而现有评测都在测孤立的物理原理；PhysVidBench 直接把 PIQA 的 383 条&quot;生活妙招&quot;改写成视频 prompt，并配一套物理显式的 upsampled 版本；评测采用三段式间接方案，AuroraCap 写 8 条分维度 caption，Gemini-2.5-Flash 只凭 caption 回答 4123 道真值全为 Yes 的题；十二个模型的结果显示空间推理与时序动态是最弱的两个维度，而物体属性最容易，且 CogVideoX-2B 全面胜过 5B、Sora 反而在简短 prompt 上更好；人工对照的 Pearson 相关在 0.45–0.69 之间，说明这套自动评测只是中等可信。</p><p><strong>3 句话版</strong>：物理常识的硬骨头是工具挪用，PIQA 里已经有现成的题库。评测器不能被允许看图脑补，所以先压成八条文字再答题。代价是分数对 caption 的描述欲单调递增，而题库里一道 No 题也没有。</p><p><strong>1 句话版</strong>：用一个看不见视频的语言模型判视频里的物理，代价是把幻觉从答题环节搬到了 captioning 环节。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的假设不是&quot;caption 会不会漏写&quot;——那一条作者在 Limitations 里已经自己认了。真正危险的是反方向的那一条：<strong>只要八条 caption 里有一条提到了某个事实，就等于视频里真的发生了那件事。</strong></p><p>为什么它最危险：评分规则是八条 caption 的<strong>析取</strong>，题库的真值<strong>全部是 Yes</strong>，而答案为 No 的题被作者主动删除。三个设计叠在一起，评测器就变成一个<strong>只能向上注水、不能向下修正</strong>的仪器（形式化见 § 6）。一个乐于用先验补全画面的 captioner 会系统性地抬高<strong>所有</strong>模型的分数，而 benchmark 里没有任何一道题能把这种抬高抓出来。</p><p>论文自己的附录就提供了反证材料。Stage 3 的完整示例里，Wan2.1-14B 生成的是&quot;牙刷弹白漆&quot;的视频，但 AuroraCap 写出的八条 caption 里反复把白色物质称为 &quot;likely toothpaste&quot;、&quot;likely a cleaning agent&quot;，并自行补出了 &quot;the substance is being squeezed from a tube&quot; 这种 prompt 里根本没有的动作。这正是作者想绕开的幻觉，只不过换了个地方发生。</p><p>作者为这条假设提供的唯一证据是人工相关性（0.45–0.69）。这个证据强度有限：相关系数只说明自动分与人工分同向变化，不能定位系统性偏置；而且人工标注用的是同一套全 Yes 题库，它测的是&quot;人与机器在同一套有偏题目上多一致&quot;，不是&quot;这套题目能不能把对与错分开&quot;。论文未报告任何假阳性率，未报告真实视频的天花板，也没有任何形式的负控制。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，目标是直接测出 § 9 的假阳性幅度。不需要重建 benchmark，因为数据集与评测代码已开源。</p><ul><li><strong>基准</strong>：取公开的 medium + hard 子集（283 条 prompt），用任意一个开源模型（Wan2.1-1.3B 即可，一张卡能跑）生成视频，跑完整的三段式流程，记下基准分。</li><li><strong>负控制一（乱配）</strong>：把每条 prompt 的问题集与<strong>另一条随机 prompt 的视频 caption</strong> 配对，重跑 Stage 3。真值仍然全是 Yes，但此时正确率应该崩到接近 0。</li><li><strong>负控制二（无证据）</strong>：把八条 caption 换成一句与场景无关的通用描述（&quot;一双手在桌面上操作物体&quot;），重跑 Stage 3，测的是语言模型的纯先验作答率。</li><li><strong>判据</strong>：若&quot;乱配&quot;分低于基准分的 10%，且&quot;无证据&quot;分接近 0，则评测器确实在读 caption，§ 9 的担忧可以降级。若&quot;乱配&quot;分能拿到基准分的一半以上，那么 leaderboard 上一半的分数与视频内容无关，模型间的个位数差距就不具备意义。</li></ul><p>整个实验只需要一个模型的生成结果加三轮 Gemini 调用，是典型的平凡基线测试，而论文里没有做。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释：排行榜测的是&quot;视频有多容易被 caption&quot;。</strong> 十二个模型的生成配置差异巨大：论文 Table 5 里 VideoCrafter2 只有 512×320、16 帧、1 秒，而 Cosmos 是 1280×704、121 帧、5 秒。caption 模型在短而糊的视频上写得必然更短，在 § 6 的析取规则下直接换算成低分，而两者的分数差距恰好与帧数差距同向。判决实验：取同一批<strong>真实视频</strong>（物理必然正确），按 Table 5 里各模型的分辨率与帧数降采样成十二个版本，跑完整流程。如果这十二个版本之间的分数差距与真实 leaderboard 的差距同量级，那么排名很大程度上是生成配置排名的伪装。</p><p><strong>可预测的失败：时序维度的低分无法归因。</strong> 作者报告 Temporal Dynamics 是最差的两个维度之一，并归因于模型不懂事件顺序。但八条 caption 的析取规则本身就不保留顺序：所有问题都是&quot;某事是否发生&quot;的存在性形式，只要事实被提及就计分，而&quot;先捏瓶子再对准蛋黄&quot;与倒过来很可能被写成同一句。因此&quot;模型不懂时序&quot;与&quot;评测器丢掉了时序&quot;对数据的预测完全一致。区分它们需要一个论文没做的对照：<strong>把人拍的真实视频送进同一套流程</strong>。如果真实视频在 TD 上也只能得三四十分，TD 的低分就是仪器的天花板而非模型的能力上限，七个维度之间的横向比较也就不成立。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：这套流程把一个从未被标定过的测量仪器（AuroraCap 加 Gemini 判官）直接当尺子去排十二个模型的序。论文只报了相关系数，而相关系数既不给假阳性率也不给分辨力，于是任何基于它的排名都无法确定地归因到模型能力。更根本的是，题库真值全为 Yes，仪器在结构上就没有被要求区分&quot;对&quot;与&quot;错&quot;，只被要求区分&quot;提到&quot;与&quot;没提到&quot;。</p><p><strong>新 framing：把评测器当成必须先标定的仪器，把分数换成可辨性指标。</strong> 不再问&quot;这段视频答对了几道题&quot;，而问&quot;这个评测器能多好地把同一场景的物理正确版本与物理错误版本分开&quot;。具体做法：每条 prompt 配一对视频，一正一负——正例可以是人拍的真实执行，负例可以是把关键步骤剪掉或顺序倒置后的版本——要求评测器做<strong>配对判别</strong>而非单侧打分。配对判别有定义良好的 50% 随机线，且对 caption 的描述欲不再单调：多写对正例和负例一样有利。</p><p><strong>可借鉴的相邻工具</strong>：信号检测论里的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span> 与判准 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 把&quot;分辨力&quot;与&quot;倾向于答 Yes&quot;分成两个数，恰好对应本文混在一起的两件事；预报评分里的 reliability diagram 能直接画出评测器的系统性偏置；LLM-as-judge 的校准文献提供了现成的偏差修正方法。</p><p><strong>第一个实验</strong>：不需要重新生成任何视频。从公开的 medium + hard 子集里抽 200 个场景，每个场景补齐真值为 No 的配对题，得到一个正负均衡的校准集；先测出现有流程的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span>，再用它们把十二个模型的原始分做偏差修正，看排名会不会翻。如果修正后头部几个模型的差距落进仪器误差带内，那么本文真正的贡献就应当重述为&quot;一个来自 PIQA 的 affordance 题库&quot;，而不是&quot;一个可用的物理常识排行榜&quot;——前者依然很有价值，但结论的强度完全不同。</p>',64)])])}const h=a(e,[["render",r]]);export{d as __pageData,h as default};
